practice_tasks.solution:
def log_request(method, *path_parts, **headers):
    path = '/' + '/'.join(path_parts)
    print(f'{method} {path}')
    for key, value in headers.items():
        print(f'{key}: {value}')

log_request('GET', 'api', 'users', Authorization='Bearer xyz', Accept='application/json')

